const t = $input.first().json;
const stripHtml = (html) => {
  if (!html) return '';
  return String(html).replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/p>/gi, '\n\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '\"').replace(/&#39;/g, "'").replace(/\n{3,}/g, '\n\n').trim();
};
const clip = (s, n) => { const x = String(s || ''); return x.length > n ? x.slice(0, n) + '\u2026' : x; };
const baseUrl = 'https://community.n8n.io';
const posts = (t.post_stream && t.post_stream.posts) || [];
const topicUrl = baseUrl + '/t/' + t.slug + '/' + t.id;
const originalPost = posts.find(p => p.post_number === 1) || posts[0];
const acceptedAnswer = posts.find(p => p.accepted_answer === true) || null;
const replies = posts.filter(p => p !== originalPost && p !== acceptedAnswer).sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 5);
const formatPost = (p, role) => p ? {
  role,
  post_number: p.post_number,
  url: topicUrl + '/' + p.post_number,
  username: p.username,
  name: p.name,
  staff: p.staff === true || p.admin === true || p.moderator === true,
  trust_level: p.trust_level,
  created_at: p.created_at,
  score: p.score,
  like_count: (p.actions_summary || []).find(a => a.id === 2) ? (p.actions_summary || []).find(a => a.id === 2).count : 0,
  body: clip(p.raw || stripHtml(p.cooked), 2500),
  accepted_answer: p.accepted_answer === true
} : null;
const out = {
  topic_id: t.id,
  title: t.fancy_title || t.title,
  url: topicUrl,
  category_id: t.category_id,
  tags: t.tags || [],
  solved: t.has_accepted_answer === true,
  closed: t.closed === true,
  archived: t.archived === true,
  archetype: t.archetype,
  posts_count: t.posts_count,
  reply_count: t.reply_count,
  views: t.views,
  like_count: t.like_count,
  created_at: t.created_at,
  last_posted_at: t.last_posted_at,
  total_posts_in_thread: (t.post_stream && t.post_stream.stream) ? t.post_stream.stream.length : posts.length,
  posts_returned: posts.length,
  original_post: formatPost(originalPost, 'question'),
  accepted_answer: formatPost(acceptedAnswer, 'accepted_answer'),
  top_replies: replies.map(p => formatPost(p, 'reply'))
};
return [out];
